// ===================================================================
// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for nt-fetc-owns against the loopback mock server
// Flo: start mock > fetch paths > assert status, body, guards
// I/O: mock responses > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const fetc = @import("nt-fetc-owns.zig"); const mock = @import("te-mock-serv.zig");
const allo = std.testing.allocator;
fn opts() fetc.Opts { return .{ .priv_allo = true, .body_maxz = 1 << 20, .time_mill = 5000 }; }
test "plain GET returns 200 and body" { var srv: mock.Mock = undefined; try srv.start(std.testing.io); defer srv.halt(); var buf: [64]u8 = undefined; var res = try fetc.fetcGet(allo, std.testing.io, srv.urlOf(&buf, "/ok"), opts(), .{}); defer res.free(allo); try std.testing.expectEqual(@as(u16, 200), res.code); try std.testing.expectEqualStrings("<html>hello</html>", res.body); try std.testing.expectEqualStrings("\"v1\"", res.etag); try std.testing.expect(std.mem.startsWith(u8, res.ctyp, "text/html")); }
test "gzip body is inflated, only gzip is offered" { var srv: mock.Mock = undefined; try srv.start(std.testing.io); defer srv.halt(); var buf: [64]u8 = undefined; var res = try fetc.fetcGet(allo, std.testing.io, srv.urlOf(&buf, "/gz"), opts(), .{}); defer res.free(allo); try std.testing.expectEqualStrings("<html>gzipped page</html>", res.body); try std.testing.expect(std.ascii.indexOfIgnoreCase(srv.hdrLast(), "accept-encoding: gzip\r\n") != null); }
test "conditional GET gives 304 with empty body" { var srv: mock.Mock = undefined; try srv.start(std.testing.io); defer srv.halt(); var buf: [64]u8 = undefined; var res = try fetc.fetcGet(allo, std.testing.io, srv.urlOf(&buf, "/cond"), opts(), .{ .etag = "\"v1\"" }); defer res.free(allo); try std.testing.expectEqual(@as(u16, 304), res.code); try std.testing.expectEqual(@as(usize, 0), res.body.len); var res2 = try fetc.fetcGet(allo, std.testing.io, srv.urlOf(&buf, "/cond"), opts(), .{}); defer res2.free(allo); try std.testing.expectEqual(@as(u16, 200), res2.code); }
test "redirect is followed by hand, final url kept" { var srv: mock.Mock = undefined; try srv.start(std.testing.io); defer srv.halt(); var buf: [64]u8 = undefined; var res = try fetc.fetcGet(allo, std.testing.io, srv.urlOf(&buf, "/redir"), opts(), .{}); defer res.free(allo); try std.testing.expectEqual(@as(u16, 200), res.code); try std.testing.expect(std.mem.endsWith(u8, res.finl, "/ok")); }
test "redirect loop refused" { var srv: mock.Mock = undefined; try srv.start(std.testing.io); defer srv.halt(); var buf: [64]u8 = undefined; try std.testing.expectError(error.RedirectLoop, fetc.fetcGet(allo, std.testing.io, srv.urlOf(&buf, "/loop"), opts(), .{})); }
test "redirect to metadata ip refused even when the first hop is allowed" { var srv: mock.Mock = undefined; try srv.start(std.testing.io); defer srv.halt(); var buf: [64]u8 = undefined; var gate = opts(); gate.priv_allo = false; try std.testing.expectError(error.BlockedHost, fetc.fetcGet(allo, std.testing.io, srv.urlOf(&buf, "/ok"), gate, .{})); }
test "oversize body refused, gzip bomb refused" { var srv: mock.Mock = undefined; try srv.start(std.testing.io); defer srv.halt(); var buf: [64]u8 = undefined; try std.testing.expectError(error.TooBig, fetc.fetcGet(allo, std.testing.io, srv.urlOf(&buf, "/big"), opts(), .{})); try std.testing.expectError(error.TooBig, fetc.fetcGet(allo, std.testing.io, srv.urlOf(&buf, "/bomb"), opts(), .{})); }
test "non-text refused before the body is read" { var srv: mock.Mock = undefined; try srv.start(std.testing.io); defer srv.halt(); var buf: [64]u8 = undefined; try std.testing.expectError(error.NotText, fetc.fetcGet(allo, std.testing.io, srv.urlOf(&buf, "/img"), opts(), .{})); }
test "status codes pass through: 403 body, 429 retry-after, 404" { var srv: mock.Mock = undefined; try srv.start(std.testing.io); defer srv.halt(); var buf: [64]u8 = undefined; var one = try fetc.fetcGet(allo, std.testing.io, srv.urlOf(&buf, "/e403"), opts(), .{}); defer one.free(allo); try std.testing.expectEqual(@as(u16, 403), one.code); var two = try fetc.fetcGet(allo, std.testing.io, srv.urlOf(&buf, "/e429"), opts(), .{}); defer two.free(allo); try std.testing.expectEqual(@as(u16, 429), two.code); try std.testing.expectEqual(@as(u32, 7), two.retr); var tri = try fetc.fetcGet(allo, std.testing.io, srv.urlOf(&buf, "/nope"), opts(), .{}); defer tri.free(allo); try std.testing.expectEqual(@as(u16, 404), tri.code); }
test "bad urls refused before any network" { try std.testing.expectError(error.BadUrl, fetc.fetcGet(allo, std.testing.io, "ftp://a.com/", opts(), .{})); try std.testing.expectError(error.BlockedHost, fetc.fetcGet(allo, std.testing.io, "http://169.254.169.254/latest", .{}, .{})); try std.testing.expectError(error.BlockedHost, fetc.fetcGet(allo, std.testing.io, "http://localhost:1/", .{}, .{})); }
